config backup/restore; live health and routes. Covered by FR-MCP-USECASE-007; TEST-MCP-USECASE-011.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-USECASE-011\u0022,\u0022Title\u0022:\u0022Graph storage\u0022,\u0022Body\u0022:\u0022JSON column graph storage; multi-provider migrations; soft-delete and workspace filters. ACs AC-T11-1..3.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-USECASE-012\u0022,\u0022Title\u0022:\u0022Diagram graph CQRS\u0022,\u0022Body\u0022:\u0022GetGraph/PutGraph/Export handlers; thin controller. ACs AC-T12-1..2.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-USECASE-013\u0022,\u0022Title\u0022:\u0022Diagram graph REST\u0022,\u0022Body\u0022:\u0022GET/PUT diagram-graph; GET diagram kind=usecase format mermaid|plantuml; sequence remains. ACs AC-T13-1..3.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-USECASE-014\u0022,\u0022Title\u0022:\u0022UML serialization service\u0022,\u0022Body\u0022:\u0022Pure DI service graph to Mermaid and PlantUML. ACs AC-T14-1..2.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-USECASE-015\u0022,\u0022Title\u0022:\u0022Canvas UI hosting\u0022,\u0022Body\u0022:\u0022Static /usecases/ canvas assets; palette; umlCanvas; REST-only. ACs AC-T15-1..2.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-USECASE-016\u0022,\u0022Title\u0022:\u0022Graph put audit\u0022,\u0022Body\u0022:\u0022Put graph emits DataAuditLog. AC-T16-1.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-VERIFYWRAP-001\u0022,\u0022Title\u0022:\u0022code-verify catch disk-full and enforce wrapper timeout\u0022,\u0022Body\u0022:\u0022code-verify.ps1 catches IOException for disk full as a typed status and applies a hard timeout around the wrapper so the console is released. Covered by FR-MCP-VERIFYWRAP-001 TEST-MCP-VERIFYWRAP-001.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022ac-1\u0022,\u0022text\u0022:\u0022code-verify catches disk-full and enforces wrapper timeout\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-VOICE-001\u0022,\u0022Title\u0022:\u0022Voice Conversation Service\u0022,\u0022Body\u0022:\u0022\\u0060VoiceConversationService\\u0060 manages the full voice session lifecycle: session creation with \\u0060CopilotInteractiveSession\\u0060 spawned via \\u0060DesktopProcessLauncher\\u0060 (or standard \\u0060Process.Start\\u0060), turn processing with tool-call loop (max \\u0060MaxToolSteps\\u0060 iterations), in-memory transcript storage, tool-call record tracking, and session cleanup. Configurable via \\u0060VoiceConversationOptions\\u0060 bound from \\u0060Mcp:Voice\\u0060 configuration section (model, timeouts, rate limits for writes/deletes per turn, transcript context limit).\\n**Covered by:** \\u0060VoiceConversationService\\u0060, \\u0060VoiceConversationOptions\\u0060, \\u0060CopilotInteractiveSession\\u0060\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-VOICE-002\u0022,\u0022Title\u0022:\u0022Voice Controller REST API\u0022,\u0022Body\u0022:\u0022\\u0060VoiceController\\u0060 at \\u0060/mcpserver/voice/session/*\\u0060 exposes 8 endpoints: \\u0060POST /\\u0060 (create session with \\u0060DeviceId\\u0060/\\u0060Language\\u0060/\\u0060ClientName\\u0060), \\u0060GET /?deviceId=\\u0060 (find by device), \\u0060POST /{id}/turn\\u0060 (synchronous turn), \\u0060POST /{id}/turn/stream\\u0060 (SSE streaming turn), \\u0060POST /{id}/interrupt\\u0060 (cancel active turn), \\u0060POST /{id}/escape\\u0060 (send ESC chars to Copilot stdin), \\u0060GET /{id}\\u0060 (session status), \\u0060GET /{id}/transcript\\u0060 (transcript entries), \\u0060DELETE /{id}\\u0060 (destroy session). DTOs: \\u0060VoiceSessionCreateRequest/Response\\u0060, \\u0060VoiceTurnRequest/Response\\u0060, \\u0060VoiceInterruptResponse\\u0060, \\u0060VoiceSessionStatusDto\\u0060, \\u0060VoiceTranscriptEntryDto/Response\\u0060, \\u0060VoiceToolCallRecordDto\\u0060, \\u0060VoiceTurnStreamEvent\\u0060.\\n**Covered by:** \\u0060VoiceController\\u0060, \\u0060VoiceConversationContracts\\u0060\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-VOICE-003\u0022,\u0022Title\u0022:\u0022Voice Session Lifecycle Management\u0022,\u0022Body\u0022:\u0022One active session per device enforced via \\u0060DeviceId\\u0060 lookup; creating a new session for a device with an active session returns the existing session. Idle timeout (\\u0060SessionIdleTimeoutMinutes\\u0060, default 15) triggers the configured idle-shutdown prompt sent to Copilot, waits for the configured sentinel response, then terminates the session. \\u0060UseDesktopLaunch\\u0060 option (default true) selects \\u0060CreateProcessAsUser\\u0060 for Windows service context.\\n**Covered by:** \\u0060VoiceConversationService.OnIdleCleanupTick\\u0060 / \\u0060CleanupIdleSessionsAsync\\u0060 (60s timer-driven idle-shutdown orchestrator), \\u0060VoiceConversationOptions.SessionIdleTimeoutMinutes\\u0060, \\u0060VoiceConversationOptions.IdleShutdownCommand\\u0060 (config string sent to Copilot), \\u0060VoiceConversationOptions.IdleShutdownSentinel\\u0060 (config string awaited as the shutdown confirmation). Note: \\u0060IdleShutdownCommand\\u0060 and \\u0060IdleShutdownSentinel\\u0060 are configured strings on \\u0060VoiceConversationOptions\\u0060, not CLR message types.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-VOICE-004\u0022,\u0022Title\u0022:\u0022Interactive Presence Signals on Stream State Changes\u0022,\u0022Body\u0022:\u0022On interactive stream disconnect, the runtime SHALL send \\u0060User is AFK.\\u0060 to the associated interactive agent session.\\nOn interactive stream reconnect, after response stream establishment, the runtime SHALL send \\u0060User is here.\\u0060 to the associated interactive agent session.\\n\\nPresence signaling SHALL be excluded from one-shot sessions.\\n\\n**Status:** \\uD83D\\uDD34 Planned\\n\\n**Covered by:** \\u0060VoiceConversationService\\u0060 *(planned extension)*, \\u0060AgentPoolStreamService\\u0060 *(planned)*\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WEB-001\u0022,\u0022Title\u0022:\u0022Web UI Ownership Boundary\u0022,\u0022Body\u0022:\u0022Web UI implementation work for the former McpServer.UI.Core and McpServer.Director surfaces SHALL be owned by the McpServerManager repository. This repository SHALL keep only server-side contracts, API behavior, and compatibility documentation required by those external UI clients.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022deferred\u0022,\u0022Notes\u0022:\u0022Deferred to McpServerManager; this repository owns only server-side contracts and compatibility documentation.\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022TR-MCP-WEB-001-AC1\u0022,\u0022text\u0022:\u0022New Web UI implementation code is not added under this repository moved UI surfaces.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred to McpServerManager.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-001-AC2\u0022,\u0022text\u0022:\u0022Server-side API changes needed by McpServerManager are tracked as MCP FR/TR/TEST items in this repository.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-001-AC3\u0022,\u0022text\u0022:\u0022Cross-repo handoffs identify the owning repository and do not silently reopen moved UI projects here.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WEB-002\u0022,\u0022Title\u0022:\u0022Web UI API Compatibility Contract\u0022,\u0022Body\u0022:\u0022Server APIs consumed by external web-management clients SHALL remain documented and version-compatible across McpServer and McpServerManager. Breaking API changes require explicit requirements updates, migration notes, and tests in the server repository before deployment.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022deferred\u0022,\u0022Notes\u0022:\u0022Deferred until the next McpServerManager integration slice.\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022TR-MCP-WEB-002-AC1\u0022,\u0022text\u0022:\u0022API changes intended for web-management clients name the consuming route, DTO, and owning client surface.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-002-AC2\u0022,\u0022text\u0022:\u0022Breaking changes include a migration note and compatibility test coverage.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-002-AC3\u0022,\u0022text\u0022:\u0022Generated requirements/wiki output reflects the current cross-repo API contract.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WEB-003\u0022,\u0022Title\u0022:\u0022Web UI Authentication And Workspace Boundary\u0022,\u0022Body\u0022:\u0022External web-management clients SHALL authenticate through the existing MCP workspace auth/token model and SHALL preserve workspace isolation. This repository SHALL provide the server-side policy and tests; client UX and screen implementation remain in McpServerManager.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022deferred\u0022,\u0022Notes\u0022:\u0022Deferred until the next McpServerManager integration slice.\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022TR-MCP-WEB-003-AC1\u0022,\u0022text\u0022:\u0022Web-client API calls use existing workspace-token/OIDC policy behavior rather than a new parallel auth path.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-003-AC2\u0022,\u0022text\u0022:\u0022Workspace-scoped requests remain isolated by the resolved workspace path.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-003-AC3\u0022,\u0022text\u0022:\u0022Any new server endpoint used by web clients includes auth and workspace-isolation tests.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WEB-004\u0022,\u0022Title\u0022:\u0022Web UI Deployment And Handoff Documentation\u0022,\u0022Body\u0022:\u0022Deployment guidance for web-management surfaces SHALL distinguish server deployment in this repository from UI/client deployment in McpServerManager. This repository SHALL document only the server prerequisites, endpoint contracts, and compatibility expectations needed for the external UI.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022deferred\u0022,\u0022Notes\u0022:\u0022Deferred until the next McpServerManager integration slice.\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022TR-MCP-WEB-004-AC1\u0022,\u0022text\u0022:\u0022Server deployment docs do not instruct agents to deploy moved UI projects from this repository.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-004-AC2\u0022,\u0022text\u0022:\u0022Handoff docs name McpServerManager as the owner for UI implementation and client deployment.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022},{\u0022id\u0022:\u0022TR-MCP-WEB-004-AC3\u0022,\u0022text\u0022:\u0022Server readiness/config validation covers the endpoints and auth policy that external UI clients depend on.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:\u0022Deferred until next integration slice.\u0022}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WIKIEXPORT-001\u0022,\u0022Title\u0022:\u0022docs/wiki.yaml export configuration loader and renderer integration\u0022,\u0022Body\u0022:\u0022Implement a typed YamlDotNet-backed docs/wiki.yaml loader, validation layer, and wiki renderer integration shared by database-backed and document-backed requirements services.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022high\u0022,\u0022Status\u0022:\u0022completed\u0022,\u0022Notes\u0022:\u0022Do not parse YAML with string or regex logic. Resolve docs/wiki.yaml under the active workspace through RequirementsOptions.WikiConfigPath.\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-001-AC1\u0022,\u0022text\u0022:\u0022RequirementsOptions exposes WikiConfigPath defaulting to docs/wiki.yaml, and services resolve it under the active workspace path or configured requirements root.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-001-AC2\u0022,\u0022text\u0022:\u0022RequirementsWikiExportConfig models deserialize docs/wiki.yaml with YamlDotNet into typed objects, with no line-based or regex YAML parsing.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-001-AC3\u0022,\u0022text\u0022:\u0022Validation rejects unsupported schema values, missing required fields, duplicate document ids, duplicate targets per platform, path traversal, reserved managed target files, unsupported generated sources, invalid platform names, missing source files, and navigation/document mismatches.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-001-AC4\u0022,\u0022text\u0022:\u0022Both RequirementsDatabaseDocumentService.GenerateWikiAsync and RequirementsDocumentService.GenerateWikiAsync share the same config loader and renderer path.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-001-AC5\u0022,\u0022text\u0022:\u0022The exporter validates all configured content before calling RequirementsDocumentExportWriter so invalid config leaves existing export files unchanged.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-001-AC6\u0022,\u0022text\u0022:\u0022Generated platform side files remain managed by the exporter, including .mcp-requirements-manifest.json, GitHub _Sidebar.md and _Footer.md, and Azure .order files.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WIKIEXPORT-002\u0022,\u0022Title\u0022:\u0022Marker writer default wiki.yaml serializer\u0022,\u0022Body\u0022:\u0022Extend MarkerFileService.WriteMarkerAsync with an idempotent default wiki.yaml writer that builds typed objects and serializes them with YamlDotNet before writing docs/wiki.yaml.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022high\u0022,\u0022Status\u0022:\u0022completed\u0022,\u0022Notes\u0022:\u0022The writer must run as part of marker creation and must preserve user-authored docs/wiki.yaml files.\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-002-AC1\u0022,\u0022text\u0022:\u0022MarkerFileService computes the default wiki config path as workspace-root/docs/wiki.yaml and creates the docs directory when needed.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-002-AC2\u0022,\u0022text\u0022:\u0022MarkerFileService checks for an existing docs/wiki.yaml before writing and skips creation when the file already exists.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-002-AC3\u0022,\u0022text\u0022:\u0022Default wiki config is represented by typed or dictionary objects and serialized with the existing YamlDotNet serializer.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-002-AC4\u0022,\u0022text\u0022:\u0022The default config targets Home.md, Functional-Requirements.md, Technical-Requirements.md, Testing-Requirements.md, TR-per-FR-Mapping.md, and Requirements-Matrix.md on both platforms.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022TR-MCP-WIKIEXPORT-002-AC5\u0022,\u0022text\u0022:\u0022A failure to create the default wiki.yaml is logged through the marker writer warning path and does not leave a partially written file.\u0022,\u0022isSatisfied\u0022:true,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WIKIEXPORT-003\u0022,\u0022Title\u0022:\u0022Dump schema and export flag\u0022,\u0022Body\u0022:\u0022schemaVersion mcp-wiki-dump/v1. SHA-256 per table plus root hash. Flag default off. tables[] uses McpDbContext DbSet names.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022AC1\u0022,\u0022text\u0022:\u0022Without dump flag, export unchanged.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC2\u0022,\u0022text\u0022:\u0022With flag, versioned JSON keyed by workspace.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC3\u0022,\u0022text\u0022:\u0022Dump TODO rows and requirement links match store.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC4\u0022,\u0022text\u0022:\u0022SHA-256 matches canonical UTF-8 JSON.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WIKIEXPORT-004\u0022,\u0022Title\u0022:\u0022Import remap and dump parameter binding\u0022,\u0022Body\u0022:\u0022Bind --dump to WorkspaceController.CreateAsync. Remap workspace id, paths, FKs. Idempotent re-import. Reject malformed dump, version mismatch, missing tables, unsafe path.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022AC1\u0022,\u0022text\u0022:\u0022Hydrates TODOs from dump not todo.yaml.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC2\u0022,\u0022text\u0022:\u0022Old workspace id absent after remap.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC3\u0022,\u0022text\u0022:\u0022Malformed dump rejected.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC4\u0022,\u0022text\u0022:\u0022Idempotent reimport no duplicate TODOs.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WIKIEXPORT-005\u0022,\u0022Title\u0022:\u0022todo.yaml archive and conflict diagnostics\u0022,\u0022Body\u0022:\u0022Discovery classifies generated/shadow/deprecated. Archive is copy then optional remove with report. Conflict diagnostic includes both paths.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022AC1\u0022,\u0022text\u0022:\u0022todo.yaml not source of truth when dump present.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC2\u0022,\u0022text\u0022:\u0022Cleanup archives with evidence, no silent delete.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022AC3\u0022,\u0022text\u0022:\u0022Dump and yaml conflict: dump wins, diagnostic names both.\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-002\u0022,\u0022Title\u0022:\u0022Workspace Service\u0022,\u0022Body\u0022:\u0022CRUD operations for workspace entities persisted in EF Core SQLite. Auto-port assignment starts at base 7147 and increments from the current maximum registered port. Init scaffolding creates the workspace directory, \\u0060docs/Project/TODO.yaml\\u0060, \\u0060docs/sessions/\\u0060, \\u0060docs/external/\\u0060, and \\u0060mcp.db\\u0060.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-003\u0022,\u0022Title\u0022:\u0022Workspace Process Manager\u0022,\u0022Body\u0022:\u0022Manages workspace marker file lifecycle. On startup, generates tokens and writes \\u0060AGENTS-README-FIRST.yaml\\u0060 marker files for all registered workspaces - all pointing to the single shared host port. On stop, removes marker files. No longer spawns child \\u0060WebApplication\\u0060 instances (replaced by single-app multi-tenant model, see TR-MCP-MT-001 through TR-MCP-MT-003).\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-004\u0022,\u0022Title\u0022:\u0022Workspace Controller\u0022,\u0022Body\u0022:\u0022REST API at \\u0060/mcpserver/workspace\\u0060 with Base64URL-encoded path keys. Provides create, read, update, delete, init, start, stop, status, and prompt (GET/PUT) endpoints. All \\u0060/mcpserver/*\\u0060 routes protected by \\u0060WorkspaceAuthMiddleware\\u0060 (per-workspace token).\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-005\u0022,\u0022Title\u0022:\u0022Marker File Service\u0022,\u0022Body\u0022:\u0022\\u0060MarkerFileService.WriteMarkerAsync\\u0060 writes \\u0060AGENTS-README-FIRST.yaml\\u0060 to the workspace root. All markers point to the same shared host port. Uses Handlebars.Net templating with full workspace context. The marker template MUST be loaded from \\u0060templates/prompt-templates.yaml\\u0060 via \\u0060PromptTemplateService\\u0060 (id: \\u0060default-marker-prompt\\u0060). **CRITICAL**: If the template cannot be loaded (missing file, invalid YAML, or missing ID), the service must log a critical error and shut down the server immediately. Fallback to hardcoded templates is PROHIBITED. The YAML file contains port, \\u0060baseUrl\\u0060, all endpoint paths, process PID, \\u0060startedAt\\u0060 timestamp, workspace name, per-workspace auth token (\\u0060apiKey\\u0060), and a machine-readable \\u0060prompt\\u0060 block. Agents should send \\u0060X-Workspace-Path\\u0060 header for workspace targeting.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-006\u0022,\u0022Title\u0022:\u0022Workspace Host Controller Isolation\u0022,\u0022Body\u0022:\u0022*Obsolete.* Replaced by single-app multi-tenant model (TR-MCP-MT-002). \\u0060ExcludeControllerFeatureProvider\\u0060 can be removed.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-007\u0022,\u0022Title\u0022:\u0022Workspace Auto-Start on Service Startup\u0022,\u0022Body\u0022:\u0022\\u0060WorkspaceProcessManager\\u0060, as an \\u0060IHostedService\\u0060, queries all registered workspaces on \\u0060StartAsync\\u0060 and writes marker files for each. Failures on individual workspace marker writes are logged and skipped rather than aborting global startup.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-008\u0022,\u0022Title\u0022:\u0022Workspace Auto-Init and Auto-Start on Creation\u0022,\u0022Body\u0022:\u0022\\u0060WorkspaceController\\u0060 POST calls \\u0060WorkspaceService.InitAsync\\u0060 to scaffold the directory structure, then calls \\u0060WorkspaceProcessManager.StartAsync\\u0060 to bring the host online, all within a single request, before returning 201 Created.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-009\u0022,\u0022Title\u0022:\u0022Primary Workspace Detection and IsEnabled Gating\u0022,\u0022Body\u0022:\u0022\\u0060WorkspaceProcessManager.IHostedService.StartAsync\\u0060 resolves the primary workspace: first by \\u0060IsPrimary = true\\u0060 \\u002B lowest port among enabled workspaces; then by lowest-port enabled workspace if none is marked primary. For the primary workspace, only a marker file is written - no child \\u0060WebApplication\\u0060 is created. Workspaces with \\u0060IsEnabled = false\\u0060 are skipped during auto-start but can be started manually.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-WS-UI-001\u0022,\u0022Title\u0022:\u0022McpServer Management Web UI\u0022,\u0022Body\u0022:\u0022Reserved/planned: web-based management UI for workspace and server administration. Tracks FR-MCP-031.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-MCP-XAGENT-001\u0022,\u0022Title\u0022:\u0022Assert-ReplCurrentTurnFresh refuses different sourceType prefixes\u0022,\u0022Body\u0022:\u0022Assert-ReplCurrentTurnFresh compares sessionId sourceType prefix. Different prefix refuses CompleteTurn persist. Same prefix still rebinds. persist identity keeps planFile/todoId. Covered by FR-MCP-XAGENT-001 TEST-MCP-XAGENT-001.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022ac-1\u0022,\u0022text\u0022:\u0022Assert-ReplCurrentTurnFresh refuses different sourceType prefixes\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-PLANNED-013A\u0022,\u0022Title\u0022:\u0022\u0022,\u0022Body\u0022:\u0022\\u0060AddControllers().ConfigureApiBehaviorOptions\\u0060 installs an \\u0060InvalidModelStateResponseFactory\\u0060 that produces \\u0060application/problem\\u002Bjson\\u0060 responses for body-binding failures on \\u0060/mcpserver/*\\u0060 endpoints. The factory strips the action parameter name (\\u0060dto\\u0060, \\u0060body\\u0060, \\u0060turn\\u0060) from the \\u0060errors\\u0060 keys, replacing them with \\u0060$\\u0060 so callers see the canonical JSON root marker instead of a misleading wrapper field name. \\u0060SessionLogController.SubmitAsync\\u0060 and \\u0060GetByIdAsync\\u0060 use \\u0060ValidationProblem\\u0060 for domain validation to keep the response shape uniform.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-PLANNED-CORE-014\u0022,\u0022Title\u0022:\u0022Problem\\u002BJSON response factory for model binding failures\u0022,\u0022Body\u0022:\u0022AddControllers().ConfigureApiBehaviorOptions installs an InvalidModelStateResponseFactory that produces application/problem\\u002Bjson responses for body-binding failures on /mcpserver/* endpoints. The factory strips the action parameter name (dto, body, turn) from the errors keys, replacing them with $ so callers see the canonical JSON root marker instead of a misleading wrapper field name. SessionLogController.SubmitAsync and GetByIdAsync use ValidationProblem for domain validation to keep the response shape uniform.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022high\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:\u0022\u0022,\u0022AcceptanceCriteria\u0022:[{\u0022id\u0022:\u0022ac-1\u0022,\u0022text\u0022:\u0022InvalidModelStateResponseFactory produces application/problem\\u002Bjson for body-binding failures on /mcpserver/* endpoints\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022ac-2\u0022,\u0022text\u0022:\u0022Factory strips action parameter names (dto, body, turn) and replaces with $ marker\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022ac-3\u0022,\u0022text\u0022:\u0022SessionLogController.SubmitAsync and GetByIdAsync use ValidationProblem for domain validation\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null},{\u0022id\u0022:\u0022ac-4\u0022,\u0022text\u0022:\u0022Response shape is uniform across model binding and domain validation failures\u0022,\u0022isSatisfied\u0022:false,\u0022evidence\u0022:null}],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-SUPPORT-010E\u0022,\u0022Title\u0022:\u0022Stateless lifecycle controller \\u002B client \\u002B tool adapters\u0022,\u0022Body\u0022:\u0022SessionLogController exposes open/begin/complete/fail keyed by ids; SessionLogClient and MCP tools delegate; UpsertTurnAsync underpins all.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-SUPPORT-010F\u0022,\u0022Title\u0022:\u0022Merge-on-null mapping for partial submits\u0022,\u0022Body\u0022:\u0022MapDtoToEntity merges non-null scalars; UpsertTurns passes mergeOmittedFields:true; collections append-only.\u0022,\u0022WorkspaceId\u0022:\u0022F:\\\\GitHub\\\\McpServer\u0022,\u0022Priority\u0022:\u0022medium\u0022,\u0022Status\u0022:\u0022pending\u0022,\u0022Notes\u0022:null,\u0022AcceptanceCriteria\u0022:[],\u0022ScopeStartLayerKey\u0022:\u0022layer-1\u0022,\u0022ScopeEndLayerKey\u0022:null},{\u0022Id\u0022:\u0022TR-SUPPORT-CORE-014\u0022,\u0022Title\u0022:\u0022Stateless lifecycle controller with client and tool adapters\u0022,\u0022Body\u0022:\u0022SessionLogController exposes open/begin/complete/fail endpoints keyed by ids; Sessio