using System.Net.Http;
using QBrainAi.Client.Models;

namespace QBrainAi.Client;

/// <summary>
/// FR-MCP-TRIAGE-001..003: Client for incidental bug triage endpoints.
/// </summary>
public sealed class TriageClient : McpClientBase
{
    /// <inheritdoc />
    public TriageClient(HttpClient http, QBrainAiClientOptions options)
        : base(http, options) { }

    internal TriageClient(HttpClient http, QBrainAiClientOptions options, WorkspacePathHolder holder)
        : base(http, options, holder) { }

    /// <summary>Submits a triage report and returns accepted queue state immediately.</summary>
    public Task<TriageReportSubmitResult> SubmitReportAsync(
        TriageReportRequest request,
        CancellationToken cancellationToken = default)
        => PostAsync<TriageReportSubmitResult>("qbrainai/triage/reports", request, cancellationToken);

    /// <summary>Gets a triage report by id.</summary>
    public Task<TriageReportDetail> GetReportAsync(string id, CancellationToken cancellationToken = default)
        => GetAsync<TriageReportDetail>($"qbrainai/triage/reports/{Encode(id)}", cancellationToken);

    /// <summary>Queries triage groups by optional status and workspace path.</summary>
    public Task<TriageGroupQueryResult> QueryGroupsAsync(
        string? status = null,
        string? workspacePath = null,
        CancellationToken cancellationToken = default)
        => GetAsync<TriageGroupQueryResult>($"qbrainai/triage/groups{BuildQueryString(status, workspacePath)}", cancellationToken);

    /// <summary>Gets triage dashboard queue buckets and AI run history for an optional workspace.</summary>
    public Task<TriageDashboardResult> GetDashboardAsync(
        string? workspacePath = null,
        CancellationToken cancellationToken = default)
        => GetAsync<TriageDashboardResult>($"qbrainai/triage/dashboard{BuildQueryString(workspacePath: workspacePath)}", cancellationToken);

    /// <summary>Gets a triage group by id.</summary>
    public Task<TriageGroupDetail> GetGroupAsync(string id, CancellationToken cancellationToken = default)
        => GetAsync<TriageGroupDetail>($"qbrainai/triage/groups/{Encode(id)}", cancellationToken);

    /// <summary>Queries AI triage research runs by optional status, group, and workspace filters.</summary>
    public Task<TriageRunQueryResult> QueryRunsAsync(
        string? status = null,
        string? groupId = null,
        string? workspacePath = null,
        CancellationToken cancellationToken = default)
        => GetAsync<TriageRunQueryResult>(
            $"qbrainai/triage/runs{BuildQueryString(status, workspacePath, groupId)}",
            cancellationToken);

    /// <summary>Gets an AI triage research run by id.</summary>
    public Task<TriageResearchRunDetail> GetRunAsync(string id, CancellationToken cancellationToken = default)
        => GetAsync<TriageResearchRunDetail>($"qbrainai/triage/runs/{Encode(id)}", cancellationToken);

    /// <summary>Queries TODO ids created by triage with persisted TODO creation timestamps.</summary>
    public Task<TriageCreatedTodoQueryResult> QueryCreatedTodosAsync(
        string? workspacePath = null,
        CancellationToken cancellationToken = default)
        => GetAsync<TriageCreatedTodoQueryResult>(
            $"qbrainai/triage/todos{BuildQueryString(workspacePath: workspacePath)}",
            cancellationToken);

    /// <summary>Flushes a triage group for immediate research eligibility.</summary>
    public Task<TriageGroupDetail> FlushGroupAsync(string id, CancellationToken cancellationToken = default)
        => PostAsync<TriageGroupDetail>($"qbrainai/triage/groups/{Encode(id)}/flush", null, cancellationToken);

    /// <summary>Retries a failed triage group.</summary>
    public Task<TriageGroupDetail> RetryGroupAsync(string id, CancellationToken cancellationToken = default)
        => RetryGroupAsync(id, force: false, cancellationToken);

    /// <summary>Retries a triage group with optional forced cancellation of the current processing run.</summary>
    public Task<TriageGroupDetail> RetryGroupAsync(
        string id,
        bool force,
        CancellationToken cancellationToken = default)
    {
        var query = force ? "?force=true" : string.Empty;
        return PostAsync<TriageGroupDetail>($"qbrainai/triage/groups/{Encode(id)}/retry{query}", null, cancellationToken);
    }

    /// <summary>Soft-deletes a triage group and its reports so they no longer appear in queries.</summary>
    public Task<TriageGroupDeleteResult> DeleteGroupAsync(string id, string? reason = null, CancellationToken cancellationToken = default)
    {
        var query = string.IsNullOrWhiteSpace(reason) ? string.Empty : $"?reason={Uri.EscapeDataString(reason)}";
        return DeleteAsync<TriageGroupDeleteResult>($"qbrainai/triage/groups/{Encode(id)}{query}", cancellationToken);
    }

